def resolve_order(graph):
    # Build the full node set (including nodes that appear only as dependencies)
    nodes = set(graph.keys())
    for deps in graph.values():
        nodes.update(deps)

    # Build adjacency: dep -> set of nodes that depend on it
    dependents = {n: set() for n in nodes}
    indegree = {n: 0 for n in nodes}
    for node, deps in graph.items():
        seen = set()
        for dep in deps:
            if dep not in seen:
                seen.add(dep)
                dependents[dep].add(node)
                indegree[node] += 1

    # Kahn's algorithm with lexicographic tie-breaking via a heap
    import heapq
    ready = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for succ in dependents[node]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                heapq.heappush(ready, succ)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")

    return order
