#include <cstdint>
#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<std::pair<std::int64_t, std::int64_t>> ranges;
    ranges.reserve(n);

    for (int i = 0; i < n; ++i) {
        std::int64_t l, r;
        std::cin >> l >> r;
        if (l > r) {
            std::cout << "INVALID" << std::endl;
            return 0;
        }
        ranges.emplace_back(l, r);
    }

    std::sort(ranges.begin(), ranges.end(),
              [](const auto& a, const auto& b) {
                  if (a.first != b.first) return a.first < b.first;
                  return a.second < b.second;
              });

    std::vector<std::pair<std::int64_t, std::int64_t>> merged;
    merged.reserve(ranges.size());

    for (const auto& range : ranges) {
        if (!merged.empty()) {
            auto& last = merged.back();
            // Merge if overlapping or immediately adjacent.
            // Overflow-safe adjacency check: l <= r + 1  <=>  l - 1 <= r
            // (l - 1 cannot overflow for signed 64-bit integers).
            if (range.first - 1 <= last.second) {
                if (range.second > last.second) last.second = range.second;
                continue;
            }
        }
        merged.push_back(range);
    }

    std::cout << merged.size() << "\n";
    for (const auto& range : merged) {
        std::cout << range.first << ' ' << range.second << '\n';
    }

    return 0;
}
