#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

static inline long long norm(long long x) {
    x %= MOD;
    if (x < 0) x += MOD;
    return x;
}

struct SegTree {
    int n;
    vector<long long> sum;
    vector<long long> mul;
    vector<long long> add;

    SegTree(const vector<long long>& a) {
        n = (int)a.size();
        sum.assign(4 * n, 0);
        mul.assign(4 * n, 1);
        add.assign(4 * n, 0);
        build(1, 0, n - 1, a);
    }

    void build(int node, int l, int r, const vector<long long>& a) {
        if (l == r) {
            sum[node] = norm(a[l]);
            return;
        }
        int mid = (l + r) / 2;
        build(node * 2, l, mid, a);
        build(node * 2 + 1, mid + 1, r, a);
        sum[node] = (sum[node * 2] + sum[node * 2 + 1]) % MOD;
    }

    void apply(int node, int l, int r, long long m, long long a) {
        sum[node] = (sum[node] * m + a * (r - l + 1)) % MOD;
        mul[node] = mul[node] * m % MOD;
        add[node] = (add[node] * m + a) % MOD;
    }

    void push(int node, int l, int r) {
        if (mul[node] == 1 && add[node] == 0) return;
        int mid = (l + r) / 2;
        apply(node * 2, l, mid, mul[node], add[node]);
        apply(node * 2 + 1, mid + 1, r, mul[node], add[node]);
        mul[node] = 1;
        add[node] = 0;
    }

    void update(int node, int l, int r, int ql, int qr, long long m, long long a) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            apply(node, l, r, m, a);
            return;
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        update(node * 2, l, mid, ql, qr, m, a);
        update(node * 2 + 1, mid + 1, r, ql, qr, m, a);
        sum[node] = (sum[node * 2] + sum[node * 2 + 1]) % MOD;
    }

    long long query(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return sum[node];
        push(node, l, r);
        int mid = (l + r) / 2;
        return (query(node * 2, l, mid, ql, qr) +
                query(node * 2 + 1, mid + 1, r, ql, qr)) % MOD;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    SegTree st(a);

    for (int i = 0; i < q; i++) {
        string op;
