using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    if (k <= 0 || k > n) {
        cout << "INVALID\n";
        return 0;
    }

    int64_t sum = 0;
    for (int i = 0; i < k; ++i) sum += a[i];

    // Monotonic deques for min and max
    deque<int> minDq, maxDq;

    // Initialize with first window
    for (int i = 0; i < k; ++i) {
        while (!minDq.empty() && a[minDq.back()] >= a[i]) minDq.pop_back();
        minDq.push_back(i);
        while (!maxDq.empty() && a[maxDq.back()] <= a[i]) maxDq.pop_back();
        maxDq.push_back(i);
    }

    for (int left = 0; left + k <= n; ++left) {
        // Remove indices that are out of the current window
        while (!minDq.empty() && minDq.front() < left) minDq.pop_front();
        while (!maxDq.empty() && maxDq.front() < left) maxDq.pop_front();

        int mn = a[minDq.front()];
        int mx = a[maxDq.front()];

        cout << sum << ' ' << mn << ' ' << mx << '\n';

        // Slide the window
        if (left + k < n) {
            sum -= a[left];
            sum += a[left + k];

            int idx = left + k;
            while (!minDq.empty() && a[minDq.back()] >= a[idx]) minDq.pop_back();
            minDq.push_back(idx);
            while (!maxDq.empty() && a[maxDq.back()] <= a[idx]) maxDq.pop_back();
            maxDq.push_back(idx);
        }
    }

    return 0;
}
