#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

struct Node {
    long long sum;
    long long mul;
    long long add;
};

class LazySegTree {
    int n;
    vector<Node> tree;
    vector<long long> arr;

    void apply(int idx, long long mul, long long add) {
        // tree[idx].sum = tree[idx].sum * mul + add * (segment length)
        // But we need to know the segment length. Instead, we store sum and the lazy tag.
        // The lazy tag represents: for each element in the segment, new_val = old_val * mul + add
        // So the new sum = old_sum * mul + add * len
        // But we don't store len in the node. Let's pass len or compute it.
        // Actually, we can store the length in the node or compute it from the tree structure.
        // Let's modify: we'll pass the length to apply, or store it.
        // Alternative: store the length in the node.
        // Let's add a len field to Node.
    }

    void apply(int idx, long long mul, long long add, int len) {
        tree[idx].sum = (tree[idx].sum * mul + add * len) % MOD;
        if (tree[idx].sum < 0) tree[idx].sum += MOD;
        // Compose lazy tags: new = old * mul + add, but the existing tag is (tree[idx].mul, tree[idx].add)
        // The existing tag means: pending update is v -> v * tree[idx].mul + tree[idx].add
        // The new update is v -> v * mul + add
        // So the composed update is: v -> (v * mul + add) * tree[idx].mul + tree[idx].add
        // = v * (mul * tree[idx].mul) + (add * tree[idx].mul + tree[idx].add)
        long long new_mul = (mul * tree[idx].mul) % MOD;
        long long new_add = (add * tree[idx].mul + tree[idx].add) % MOD;
        tree[idx].mul = new_mul;
        tree[idx].add = new_add;
        if (tree[idx].mul < 0) tree[idx].mul += MOD;
        if (tree[idx].add < 0) tree[idx].add += MOD;
    }

    void push(int idx, int l, int r) {
        if (tree[idx].mul == 1 && tree[idx].add == 0) return;
        int mid = (l + r) / 2;
        int left_len = mid - l + 1;
        int right_len = r - mid;
        apply(idx * 2 + 1, tree[idx].mul, tree[idx].add, left_len);
        apply(idx * 2 + 2, tree[idx].mul, tree[idx].add, right_len);
        tree[idx].mul = 1;
        tree[idx].add = 0;
    }

    void build(int idx, int l, int r) {
        tree[idx].mul = 1;
        tree[idx].add = 0;
        if (l == r) {
            tree[idx].sum = arr[l] % MOD;
            if (tree[idx].sum < 0) tree[idx].sum += MOD;
            return;
        }
        int mid = (l + r) / 2;
        build(idx * 2 + 1, l, mid);
        build(idx * 2 + 2, mid + 1, r);
        tree[idx].sum = (tree[idx * 2 + 1].sum + tree[idx * 2 + 2].sum) % MOD;
    }

    void update(int idx, int l, int r, int ql, int qr, long long mul, long long add) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            int len = r - l + 1;
            apply(idx, mul, add, len);
            return;
        }
        push(idx, l, r);
        int mid = (l + r) / 2;
        update(idx * 2 + 1, l, mid, ql, qr, mul, add);
        update(idx * 2 + 2, mid + 1, r, ql, qr, mul, add);
        tree[idx].sum = (tree[idx * 2 + 1].sum + tree[idx * 2 + 2].sum) % MOD;
    }

    long long query(int idx, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) {
            return tree[idx].sum;
        }
        push(idx, l, r);
        int mid = (l + r) / 2;
        long long left_sum = query(idx * 2 + 1, l, mid, ql, qr);
        long long right_sum = query(idx * 2 + 2, mid + 1, r, ql, qr);
        return (left_sum + right_sum) % MOD;
    }

public:
    LazySegTree(const vector<long long>& a) : arr(a) {
        n = a.size();
        tree.resize(4 * n);
        build(1, 0, n - 1);
    }

    void range_add(int l, int r, long long x) {
        x %= MOD;
        if (x < 0) x += MOD;
        update(1, 0, n - 1, l, r, 1, x);
    }

    void range_mul(int l, int r, long long x) {
        x %= MOD;
        if (x < 0) x += MOD;
        update(1, 0, n - 1, l, r, x, 0);
    }

    long long range_sum(int l, int r) {
        long long res = query(1, 0, n - 1, l, r);
        res %= MOD;
        if (res < 0) res += MOD;
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if (!(cin >> n >> q)) return 0;

    vector<long long> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    LazySegTree seg(arr);

    string op;
    for (int i = 0; i < q; i++) {
        cin >> op;
        if (op == "ADD") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            seg.range_add(l, r, x);
        } else if (op == "MUL") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            seg.range_mul(l, r, x);
        } else if (op == "SUM") {
            int l, r;
            cin >> l >> r;
            cout << seg.range_sum(l, r) << "\n";
        }
    }

    return 0;
}
