from functools import wraps


def retry(max_attempts, exceptions=(Exception,)):
    # Validate max_attempts at construction time
    if max_attempts <= 0:
        raise ValueError("max_attempts must be a positive integer")

    # Allow exceptions to be a single class or a tuple
    if not isinstance(exceptions, tuple):
        exceptions = (exceptions,)

    def decorate(fn):
        @wraps(fn)
        def wrapped(*args, **kwargs):
            # Per-invocation attempt counter
            attempts = 0
            last_exception = None
            while attempts < max_attempts:
                attempts += 1
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    if attempts >= max_attempts:
                        raise
            # Should not reach here, but re-raise last exception if we do
            if last_exception is not None:
                raise last_exception
            return None
        return wrapped
    return decorate
