def resolve_order(graph):
    # Build the full set of nodes and dependency relationships
    # We need to include nodes that appear only in dependency lists

    # First pass: collect all nodes and their dependencies
    # We'll work with copies to avoid mutating the original
    all_nodes = set()
    deps = {}  # node -> set of its dependencies

    for node, dep_list in graph.items():
        all_nodes.add(node)
        if node not in deps:
            deps[node] = set()
        for d in dep_list:
            all_nodes.add(d)
            deps[node].add(d)

    # Ensure every node has an entry in deps (even if no dependencies)
    for node in all_nodes:
        if node not in deps:
            deps[node] = set()

    # Compute in-degree: number of dependencies not yet emitted
    # Actually, for topological sort: a node is eligible when all its dependencies have been emitted
    # So we track how many dependencies each node still has (in-degree in the dependency graph)
    # Wait: if A depends on B, then B must come before A. So edge B -> A in the "must come before" graph.
    # In-degree of A = number of dependencies of A (i.e., how many nodes must come before A)

    in_degree = {}
    for node in all_nodes:
        in_degree[node] = len(deps[node])

    # Build reverse adjacency: for each dependency, which nodes depend on it
    # This helps us update in-degrees when we emit a node
    dependents = {node: [] for node in all_nodes}
    for node in all_nodes:
        for d in deps[node]:
            dependents[d].append(node)

    # Use a min-heap for lexicographic tie-breaking
    import heapq

    # Initialize heap with all nodes that have in_degree 0
    heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    emitted = set()

    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        emitted.add(node)

        # For each node that depends on this node, decrement its in-degree
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in graph")

    return result
