    ranges.reserve(n);

    for (int i = 0; i < n; i++) {
        long long l, r;
        cin >> l >> r;
        if (l > r) {
            cout << "INVALID\n";
            return 0;
        }
        ranges.push_back({l, r});
    }

    if (ranges.empty()) {
        cout << "0\n";
        return 0;
    }

    sort(ranges.begin(), ranges.end(), [](const auto& a, const auto& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    vector<pair<long long, long long>> merged;
    merged.push_back(ranges[0]);

    for (size_t i = 1; i < ranges.size(); i++) {
        auto& last = merged.back();
        auto& cur = ranges[i];

        // Check if cur overlaps or is adjacent to last
        // Adjacent means cur.first == last.second + 1
        // But we must be careful with overflow: if last.second == INT64_MAX, then last.second + 1 overflows
        // So: they are adjacent if cur.first == last.second + 1, which is safe to check as:
        //   cur.first > last.second && cur.first - last.second == 1
        // This avoids overflow because if cur.first > last.second, then cur.first - last.second is positive and fits in int64.
        // Overlap: cur.first <= last.second
        // Adjacent: cur.first == last.second + 1, i.e., cur.first > last.second && cur.first - last.second == 1

        if (cur.first <= last.second) {
            // Overlapping
            if (cur.second > last.second) {
                last.second = cur.second;
            }
        } else if (cur.first - last.second == 1) {
            // Adjacent (safe check: cur.first > last.second is implied by the else branch)
            if (cur.second > last.second) {
                last.second = cur.second;
            }
        } else {
            merged.push_back(cur);
        }
    }

    cout << merged.size() << "\n";
    for (const auto& p : merged) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}
