#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

struct LazySegTree {
    int n;
    vector<long long> tree;   // sum of segment
    vector<long long> lazyMul;
    vector<long long> lazyAdd;
    vector<long long> segLen; // length of segment (for applying add)

    // Normalize a value into [0, MOD)
    static long long norm(long long x) {
        x %= MOD;
        if (x < 0) x += MOD;
        return x;
    }

    // Build from initial array
    void build(const vector<long long>& arr) {
        n = (int)arr.size();
        int size = 1;
        while (size < n) size <<= 1;
        tree.assign(4 * size, 0);
        lazyMul.assign(4 * size, 1);
        lazyAdd.assign(4 * size, 0);
        segLen.assign(4 * size, 0);
        buildRec(1, 0, size - 1, arr);
    }

    void buildRec(int node, int l, int r, const vector<long long>& arr) {
        segLen[node] = r - l + 1;
        if (l == r) {
            if (l < (int)arr.size()) {
                tree[node] = norm(arr[l]);
            } else {
                tree[node] = 0;
            }
            return;
        }
        int mid = (l + r) / 2;
        buildRec(node * 2, l, mid, arr);
        buildRec(node * 2 + 1, mid + 1, r, arr);
        tree[node] = (tree[node * 2] + tree[node * 2 + 1]) % MOD;
    }

    // Apply affine transform (mul, add) to node
    void apply(int node, long long mul, long long add) {
        // tree[node] = tree[node] * mul + add * segLen[node]
        tree[node] = (tree[node] * mul + add * segLen[node]) % MOD;
        // Compose lazy: existing (lazyMul[node], lazyAdd[node]) then new (mul, add)
        // new state: (lazyMul * mul, lazyAdd * mul + add)
        lazyMul[node] = (lazyMul[node] * mul) % MOD;
        lazyAdd[node] = (lazyAdd[node] * mul + add) % MOD;
    }

    void push(int node) {
        if (lazyMul[node] == 1 && lazyAdd[node] == 0) return;
        apply(node * 2, lazyMul[node], lazyAdd[node]);
        apply(node * 2 + 1, lazyMul[node], lazyAdd[node]);
        lazyMul[node] = 1;
        lazyAdd[node] = 0;
    }

    void update(int node, int l, int r, int ql, int qr, long long mul, long long add) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            apply(node, mul, add);
            return;
        }
        push(node);
        int mid = (l + r) / 2;
        update(node * 2, l, mid, ql, qr, mul, add);
        update(node * 2 + 1, mid + 1, r, ql, qr, mul, add);
        tree[node] = (tree[node * 2] + tree[node * 2 + 1]) % MOD;
    }

    long long query(int node, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return tree[node];
        push(node);
        int mid = (l + r) / 2;
        long long left = query(node * 2, l, mid, ql, qr);
        long long right = query(node * 2 + 1, mid + 1, r, ql, qr);
        return (left + right) % MOD;
    }

    // Public interfaces
    void add(int l, int r, long long x) {
        x = norm(x);
        update(1, 0, (1 << (int)ceil(log2((double)n))) - 1, l, r, 1, x);
    }

    void mul(int l, int r, long long x) {
        x = norm(x);
        update(1, 0, (1 << (int)ceil(log2((double)n))) - 1, l, r, x, 0);
    }

    long long sum(int l, int r) {
        return query(1, 0, (1 << (int)ceil(log2((double)n))) - 1, l, r);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<long long> arr(n);
    for (int i = 0; i < n; i++) {
