def resolve_order(graph):
    # Build the full set of nodes: keys and all dependencies
    nodes = set(graph.keys())
    for deps in graph.values():
        nodes.update(deps)

    # Build adjacency: node -> set of its dependencies (what must come before it)
    # We need in-degree style: for topological sort, we track how many dependencies
    # each node still has unresolved.

    # dep_map: node -> set of dependencies
    dep_map = {}
    for node, deps in graph.items():
        dep_map[node] = set(deps)
    # Nodes that only appear as dependencies have no outgoing deps in graph,
    # but they may have dependencies if they are also keys. If not in graph,
    # their dep set is empty.
    for node in nodes:
        if node not in dep_map:
            dep_map[node] = set()

    # remaining_deps: node -> number of dependencies not yet emitted
    remaining = {}
    for node in nodes:
        remaining[node] = len(dep_map[node])

    # reverse_adj: dep -> set of nodes that depend on dep
    reverse_adj = {node: set() for node in nodes}
    for node, deps in dep_map.items():
        for dep in deps:
            reverse_adj[dep].add(node)

    # Use a heap for lexicographic tie-breaking
    import heapq
    heap = []
    for node in nodes:
        if remaining[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in reverse_adj[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result
