int main() {
    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<std::pair<int64_t, int64_t>> ranges;
    ranges.reserve(n);

    for (int i = 0; i < n; ++i) {
        int64_t l, r;
        std::cin >> l >> r;
        if (l > r) {
            std::cout << "INVALID\n";
            return 0;
        }
        ranges.emplace_back(l, r);
    }

    std::sort(ranges.begin(), ranges.end(),
              [](const auto& a, const auto& b) {
                  if (a.first != b.first) return a.first < b.first;
                  return a.second < b.second;
              });

    std::vector<std::pair<int64_t, int64_t>> merged;
    merged.reserve(ranges.size());

    for (const auto& range : ranges) {
        if (merged.empty()) {
            merged.push_back(range);
        } else {
            auto& last = merged.back();
            // Merge if current range starts at or before last.r + 1
            // Safe check: last.r + 1 >= range.first
            // Equivalent to: last.r >= range.first - 1
            // But range.first - 1 can underflow if range.first == INT64_MIN
            // Alternative: last.r + 1 >= range.first
            // If last.r == INT64_MAX, then last.r + 1 overflows.
            // So check: if last.r == INT64_MAX, they always merge (since range.first <= INT64_MAX).
            // Otherwise, check last.r + 1 >= range.first.
            if (last.second == INT64_MAX) {
                // Always merges since range.first <= INT64_MAX
                last.second = std::max(last.second, range.second);
            } else {
                // last.second + 1 is safe (no overflow since last.second < INT64_MAX)
                if (last.second + 1 >= range.first) {
                    last.second = std::max(last.second, range.second);
                } else {
                    merged.push_back(range);
                }
            }
        }
    }

    std::cout << merged.size() << '\n';
    for (const auto& [l, r] : merged) {
        std::cout << l << ' ' << r << '\n';
    }

    return 0;
}
