int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<std::pair<int64_t, int64_t>> ranges(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> ranges[i].first >> ranges[i].second;
        if (ranges[i].first > ranges[i].second) {
            std::cout << "INVALID\n";
            return 0;
        }
    }

    // Sort by start, then by end
    std::sort(ranges.begin(), ranges.end(),
              [](const auto& a, const auto& b) {
                  if (a.first != b.first) return a.first < b.first;
                  return a.second < b.second;
              });

    std::vector<std::pair<int64_t, int64_t>> merged;
    merged.reserve(n);

    for (const auto& [l, r] : ranges) {
        if (merged.empty()) {
            merged.push_back({l, r});
        } else {
            const auto& [last_l, last_r] = merged.back();
            // Check adjacency without overflow:
            // Two ranges [a,b] and [c,d] are adjacent if b + 1 == c.
            // Since c > b (sorted), we check c == b + 1 safely by checking
            // c == b + 1 using a conditional that avoids overflow when b == INT64_MAX.
            bool adjacent = false;
            if (last_r == std::numeric_limits<int64_t>::max()) {
                // b == INT64_MAX, so b+1 would overflow. Adjacent only if c == INT64_MAX + 1,
                // which is impossible since c is int64_t. So adjacent is false.
                adjacent = false;
            } else {
                // Safe to compute last_r + 1
                adjacent = (last_r + 1 == l);
            }

            if (adjacent) {
                // Merge: extend the current range
                if (r > last_r) {
                    merged.back().second = r;
                }
            } else {
                merged.push_back({l, r});
            }
        }
    }

    std::cout << merged.size() << "\n";
    for (const auto& [l, r] : merged) {
        std::cout << l << " " << r << "\n";
    }

    return 0;
}
