using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<int64_t> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    if (k <= 0 || k > n) {
        cout << "INVALID\n";
        return 0;
    }

    // Monotonic deque for minimum
    deque<int> min_deque;
    // Monotonic deque for maximum
    deque<int> max_deque;

    int64_t sum = 0;
    for (int i = 0; i < k; ++i) {
        sum += a[i];
        while (!min_deque.empty() && min_deque.back() > a[i]) {
            min_deque.pop_back();
        }
        min_deque.push_back(a[i]);
        while (!max_deque.empty() && max_deque.back() < a[i]) {
            max_deque.pop_back();
        }
        max_deque.push_back(a[i]);
    }

    for (int left = 0; left + k <= n; ++left) {
        cout << sum << ' ' << min_deque.front() << ' ' << max_deque.front() << '\n';

        // Slide window: remove a[left], add a[left + k]
        if (left + k < n) {
            sum -= a[left];
            sum += a[left + k];

            // Update min deque
            while (!min_deque.empty() && min_deque.back() > a[left + k]) {
                min_deque.pop_back();
            }
            min_deque.push_back(a[left + k]);

            // Update max deque
            while (!max_deque.empty() && max_deque.back() < a[left + k]) {
                max_deque.pop_back();
            }
            max_deque.push_back(a[left + k]);

            // Remove element that slid out of the window
            if (min_deque.front() == a[left]) {
                min_deque.pop_front();
            }
            if (max_deque.front() == a[left]) {
                max_deque.pop_front();
            }
        }
    }

    return 0;
}
