#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007LL;

struct LazySegmentTree {
    int n;
    int64 M = MOD;
    vector<int64> tree;
    vector<pair<int64,int64>> lazy; // (mul, add)

    LazySegmentTree(int64 _n, const vector<int64>& arr) {
        n = (int)_n;
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, {1, 0});

        build(arr, 1, 0, n - 1);
    }

    void build(const vector<int64>& arr, int node, int l, int r) {
        if (l == r) {
            tree[node] = arr[l];
            return;
        }
        int mid = l + (r - l) / 2;
        build(arr, node * 2, l, mid);
        build(arr, node * 2 + 1, mid + 1, r);
        tree[node] = (tree[node * 2] + tree[node * 2 + 1]) % M;
    }

    // Compose new operation (m2, a2) over existing lazy (m1, a1)
    // New state: (m1 * m2, a1 * m2 + a2)
    static pair<int64,int64> compose(pair<int64,int64> existing, pair<int64,int64> newOp) {
        int64 m1 = existing.first;
        int64 a1 = existing.second;
        int64 m2 = newOp.first;
        int64 a2 = newOp.second;
        return {
            (m1 * m2) % M,
            (a1 * m2 + a2) % M
        };
    }

    // Push lazy tags down to children
    void push(int node, int l, int r) {
        if (lazy[node].first == 1 && lazy[node].second == 0) return;

        int mid = l + (r - l) / 2;
        int left = node * 2;
        int right = node * 2 + 1;

        // Apply current lazy to left child
        auto newLazy = compose(lazy[left], lazy[node]);
        lazy[left] = newLazy;
        tree[left] = (tree[left] * lazy[node].first + lazy[node].second) % M;

        // Apply current lazy to right child
        newLazy = compose(lazy[right], lazy[node]);
        lazy[right] = newLazy;
        tree[right] = (tree[right] * lazy[node].first + lazy[node].second) % M;

        // Reset current node's lazy
        lazy[node] = {1, 0};
    }

    // Range add: add x to [l, r]
    void range_add(int l, int r, int64 x) {
        update_add(1, 0, n - 1, l, r, x);
    }

    void update_add(int node, int l, int r, int ql, int qr, int64 x) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            lazy[node] = compose(lazy[node], {1, x});
            tree[node] = (tree[node] + x) % M;
            return;
        }
        push(node, l, r);
        int mid = l + (r - l) / 2;
        update_add(node * 2, l, mid, ql, qr, x);
        update_add(node * 2 + 1, mid + 1, r, ql, qr, x);
        tree[node] = (tree[node * 2] + tree[node * 2 + 1]) % M;
    }

    // Range multiply: multiply [l, r] by x
    void range_mul(int l, int r, int64 x) {
        update_mul(1, 0, n - 1, l, r, x);
    }

    void update_mul(int node, int l, int r, int ql, int qr, int64 x) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            lazy[node] = compose(lazy[node], {x, 0});
            tree[node] = (tree[node] * x) % M;
            return;
        }
        push(node, l, r);
        int mid = l + (r - l) / 2;
        update_mul(node * 2, l, mid, ql, qr, x);
        update_mul(node * 2 + 1, mid + 1, r, ql, qr, x);
        tree[node] = (tree[node * 2] + tree[node * 2 + 1]) % M;
    }

    // Range sum query
    int64 range_sum(int l, int r) {
        return query_sum(1, 0, n - 1, l, r);
    }

    int64 query_sum(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return tree[node];
        push(node, l, r);
        int mid = l + (r - l) / 2;
        return (query_sum(node * 2, l, mid, ql, qr) +
                query_sum(node * 2 + 1, mid + 1, r, ql, qr)) % M;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<int64> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        a[i] %= MOD;
        if (a[i] < 0) a[i] += MOD;
    }

    LazySegmentTree st(n, a);

    for (int k = 0; k < q; ++k) {
        string type;
        cin >> type;
        if (type == "ADD") {
            int l, r;
            int64 x;
            cin >> l >> r >> x;
            x %= MOD;
            if (x < 0) x += MOD;
            st.range_add(l, r, x);
        } else if (type == "MUL") {
            int l, r;
            int64 x;
            cin >> l >> r >> x;
            x %= MOD;
            if (x < 0) x += MOD;
            st.range_mul(l, r, x);
        } else if (type == "SUM") {
            int l, r;
            cin >> l >> r;
            int64 ans = st.range_sum(l, r);
            cout << ans << "\n";
        }
    }

    return 0;
}
